-- ============================================================================
-- order_number generated by the database (W5d / E3, ND-7).   PREPARED, NOT APPLIED
-- ============================================================================
-- WHY: the client draws 5 random digits per day and retries up to 3 times on collision (birthday collisions get likely
--   past ~300 orders/day). The database already has the pieces (order_sequence, generate_order_number(), and the
--   BEFORE INSERT trigger trigger_set_order_number that fills a NULL order_number), but generate_order_number()
--   left-pads the counter to 4 digits with a function that TRUNCATES longer strings, so from the 10000th order on it
--   repeats numbers and violates orders_order_number_key.
--
-- WHAT:
--   * generate_order_number() = 'ORD-' || YYYYMMDD || '-' || nextval(order_sequence)::text, no padding, same
--     SECURITY INVOKER and pinned search_path. The counter is global (not per day): format ORD-20261024-100001.
--   * The sequence is raised to a floor of 100000 (never moved backwards: GREATEST with its current position, so
--     re-running the migration after orders exist cannot cause duplicates). 6-digit numbers can never collide with
--     the 5-digit random numbers cached old bundles keep sending during the deploy; those still work because the
--     trigger only fills a NULL order_number.
--   * orders.order_number is text with only a UNIQUE constraint: the 19 characters fit.
--
-- EXECUTE: set_order_number() (invoker) calls generate_order_number() under the caller's rights, so authenticated and
--   service_role keep an explicit EXECUTE (anon does not; see 20261024100100_revoke_execute_helpers.sql). Both also get
--   USAGE on the sequence (authenticated already had it; the harness' service_role did not, and edge functions or
--   maintenance inserting an order without a number would fail with "permission denied for sequence").
--
-- Deploy order: this migration FIRST, then the front that stops sending order_number (the old front keeps working
--   with the migration applied). Needs the owner's "dale" to apply remotely.
-- ROLLBACK: supabase/rollbacks/20261024100200_order_number_sequence_down.sql restores the previous function body.
--   The sequence is not rolled back (a setval backwards would only risk duplicates).
-- ============================================================================

BEGIN;

SET LOCAL lock_timeout = '5s';

-- The function is only useful if the BEFORE INSERT trigger calls it when order_number is NULL.
DO $guard$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_trigger
     WHERE tgrelid = 'public.orders'::regclass AND tgname = 'trigger_set_order_number' AND NOT tgisinternal
  ) THEN
    RAISE EXCEPTION 'order_number_sequence: trigger trigger_set_order_number is missing on public.orders';
  END IF;
END
$guard$;

CREATE OR REPLACE FUNCTION public.generate_order_number()
RETURNS text
LANGUAGE plpgsql
SET search_path = public, pg_temp
AS $function$
BEGIN
  RETURN 'ORD-' || to_char(now(), 'YYYYMMDD') || '-' || nextval('public.order_sequence')::text;
END;
$function$;

REVOKE ALL ON FUNCTION public.generate_order_number() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.generate_order_number() TO authenticated, service_role;

-- Every insert without order_number now draws from the sequence under the inserting role's rights.
GRANT USAGE ON SEQUENCE public.order_sequence TO authenticated, service_role;

SELECT setval(
  'public.order_sequence',
  GREATEST(100000, (SELECT CASE WHEN is_called THEN last_value + 1 ELSE last_value END FROM public.order_sequence)),
  false
);

COMMIT;
